    ignore_spiders = [
        'mercado_libre_spider.py', 'opensooq_spider.py', 'coinafrique_spider.py', 
        'gumtree_spider.py', 'afribaba_spider.py', 'olx_regional_spider.py'
    ]
    
    country_stats = {}
    
    for filename in os.listdir(spider_dir):
        if not filename.endswith('spider.py') or filename in ignore_spiders:
            continue
            
        path = os.path.join(spider_dir, filename)
        try:
            with open(path, 'r', encoding='utf-8') as f:
                content = f.read()
                content_lower = content.lower()
                
                match = territory_pattern.search(content)
                if match:
                    country = match.group(1).strip()
                else:
                    continue
                
                if country not in country_stats:
                    country_stats[country] = {'total': 0, 'c2c': 0}
                
                is_c2c = any(keyword.lower() in content_lower for keyword in c2c_keywords)
                country_stats[country]['total'] += 1
                if is_c2c:
                    country_stats[country]['c2c'] += 1
        except Exception:
            pass

    inadequate = []
    thin = []
    
    for k in pop_map:
        if k not in country_stats and k not in ["USA", "UK"]:
            country_stats[k] = {'total': 0, 'c2c': 0}

    for country, stats in country_stats.items():
        pop_m = pop_map.get(country)
        if pop_m is None:
            for k, v in pop_map.items():
                if country.lower() == k.lower():
                    pop_m = v
                    break
                    
        if pop_m is None:
            continue
            
        c2c = stats['c2c']
        
        is_thin = False
        is_inadequate = False
        
        # DOUBLED THRESHOLDS + BOOK MARKET ADJUSTMENT
        threshold = 2
        if pop_m >= 100: threshold = 14
        elif pop_m >= 50: threshold = 10
        elif pop_m >= 20: threshold = 6
        elif pop_m >= 5: threshold = 4
        
        major_book_markets = [
            "United States", "USA", "China", "Germany", "United Kingdom", "UK", 
            "Japan", "France", "Italy", "Spain", "South Korea", "Canada", 
            "Brazil", "India", "Australia", "Netherlands", "Russia"
        ]
        
        if country in major_book_markets:
            threshold = int(threshold * 2)
            
        if c2c < threshold: is_thin = True
        
        if c2c == 0:
            is_inadequate = True
            is_thin = False
            
        if is_inadequate:
            inadequate.append({"c": country, "pop": pop_m, "c2c": c2c, "tot": stats['total']})
        elif is_thin:
            thin.append({"c": country, "pop": pop_m, "c2c": c2c, "tot": stats['total']})

    inadequate.sort(key=lambda x: x['pop'], reverse=True)
    thin.sort(key=lambda x: x['pop'], reverse=True)
    
    print("=== INADEQUATE C2C COVERAGE (0 Native C2C Spiders) ===")
    for item in inadequate:
        print(f"{item['c']} ({item['pop']}M pop): 0 C2C spiders (Total Spiders: {item['tot']})")
    if not inadequate: print("None!")
        
    print("\\n=== THIN C2C COVERAGE (DOUBLED Thresholds Applied) ===")
    for item in thin:
        print(f"{item['c']} ({item['pop']}M pop): {item['c2c']} C2C spiders (Total Spiders: {item['tot']})")
    if not thin: print("None!")

